### acquire-request-lock.sql
-- Serializes attempts sharing a request ID, including attempts for different items.
SELECT pg_advisory_xact_lock(hashtextextended(CAST(:request_id AS text), 0));


### create-reservation.sql
INSERT INTO inventory_reservations (request_id, inventory_item_id, quantity)
VALUES (:request_id, :inventory_item_id, :quantity)
RETURNING request_id, inventory_item_id, quantity;


### create-reserved-event.sql
INSERT INTO inventory_events (request_id, inventory_item_id, event_type, quantity)
VALUES (:request_id, :inventory_item_id, 'reserved', :quantity);


### decrement-inventory.sql
UPDATE inventory_items
SET quantity = quantity - :quantity
WHERE id = :inventory_item_id
  AND quantity >= :quantity
RETURNING id;


### find-by-request-id.sql
SELECT request_id, inventory_item_id, quantity
FROM inventory_reservations
WHERE request_id = :request_id;


### lock-inventory-item.sql
SELECT id
FROM inventory_items
WHERE id = :inventory_item_id
FOR UPDATE;

